import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { embed4Schema, type Embed4 } from "./embed4.js";
import { view7Schema, type View7 } from "./view7.js";

/**
 * The initial privacy settings of videos generated by streaming to the event as well as the embed
 * privacy of the entire collection.
 */
export type StreamPrivacy = {
  /**
   * The event's embed permission setting.
   *
   * Option descriptions:
   *  * `private` - The event can't be embedded on any domain.
   *  * `public` - The event can be embedded on any domain.
   *  * `whitelist` - The event can be embedded on permitted domains only.
   */
  embed: Embed4;
  /** The hash for unlisted events. */
  unlistedHash: string | null;
  /**
   * The general privacy setting for generated videos and the embed privacy of the entire
   * collection.
   *
   * Option descriptions:
   *  * `anybody` - Anyone can access the videos. This privacy setting appears as `Public` on the
   *    Vimeo front end.
   *  * `embed_only` - The videos don't appear on Vimeo, but they can be embedded elsewhere.
   *  * `nobody` - Only the event owner can access the videos. This privacy setting appears as
   *    `Private` on the Vimeo front end.
   *  * `password` - Only those with the password can access the videos.
   *  * `team` - Anyone on this team can access the videos. This privacy setting appears as `Company
   *    only` on the Vimeo front end.
   *  * `unlisted` - Only those with the private link can access the videos.
   */
  view: View7;
};

export const streamPrivacySchema: Schema<StreamPrivacy> = s.object<StreamPrivacy>({
  embed: embed4Schema,
  unlistedHash: s.nullable(s.string()),
  view: view7Schema,
  _keysMap: {
    unlistedHash: "unlisted_hash",
  },
});
